Here is the commit message:
bpf: reject short IPv4/IPv6 inputs in bpf_prog_test_run_skb

bpf_prog_test_run_skb() calls eth_type_trans() first and then uses
skb->protocol to initialize sk family and address fields for the test
run.

For IPv4 and IPv6 packets, it may access ip_hdr(skb) or ipv6_hdr(skb)
even when the provided test input only contains an Ethernet header.

Reject the input earlier if the Ethernet frame carries IPv4/IPv6
EtherType but the L3 header is too short.

Fold the IPv4/IPv6 header length checks into the existing protocol
switch and return -EINVAL before accessing the network headers.

Fixes: fa5cb548ced6 ("bpf: Setup socket family and addresses in bpf_prog_test_run_skb")
Reported-by: syzbot+619b9ef527f510a57cfc@syzkaller.appspotmail.com
Closes: https://syzkaller.appspot.com/bug?extid=619b9ef527f510a57cfc
Signed-off-by: Sun Jian <sun.jian.kdev@gmail.com>
Link: https://lore.kernel.org/r/20260408034623.180320-2-sun.jian.kdev@gmail.com
Signed-off-by: Alexei Starovoitov <ast@kernel.org>

Here is the root cause:
In bpf_prog_test_run_skb(), after eth_type_trans() sets skb->protocol based on the Ethernet header, the code for IPv4 and IPv6 cases unconditionally accessed ip_hdr(skb) or ipv6_hdr(skb) to set socket addresses without verifying that the skb headlen was at least the size of the respective IP header. This allowed a short input (e.g., only an Ethernet header) to cause an out-of-bounds read when dereferencing the network header pointers.

Here is the patch:

 int bpf_prog_test_run_skb(struct bpf_prog *prog, const union bpf_attr *kattr,
 			  union bpf_attr __user *uattr)
 {
 	bool is_l2 = false, is_direct_pkt_access = false, is_lwt = false;
 	u32 tailroom = SKB_DATA_ALIGN(sizeof(struct skb_shared_info));
 	struct net *net = current->nsproxy->net_ns;
 	struct net_device *dev = net->loopback_dev;
 	u32 headroom = NET_SKB_PAD + NET_IP_ALIGN;
 	u32 linear_sz = kattr->test.data_size_in;
 	u32 repeat = kattr->test.repeat;
 	struct __sk_buff *ctx = NULL;
 	struct sk_buff *skb = NULL;
 	struct sock *sk = NULL;
 	u32 retval, duration;
 	int hh_len = ETH_HLEN;
 	void *data = NULL;
 	int ret;

 	if ((kattr->test.flags & ~BPF_F_TEST_SKB_CHECKSUM_COMPLETE) ||
 	    kattr->test.cpu || kattr->test.batch_size)
 		return -EINVAL;

 	if (kattr->test.data_size_in < ETH_HLEN)
 		return -EINVAL;

 	switch (prog->type) {
 	case BPF_PROG_TYPE_SCHED_CLS:
 	case BPF_PROG_TYPE_SCHED_ACT:
 		is_direct_pkt_access = true;
 		is_l2 = true;
 		break;
 	case BPF_PROG_TYPE_LWT_IN:
 	case BPF_PROG_TYPE_LWT_OUT:
 	case BPF_PROG_TYPE_LWT_XMIT:
 		is_lwt = true;
 		fallthrough;
 	case BPF_PROG_TYPE_CGROUP_SKB:
 		is_direct_pkt_access = true;
 		break;
 	default:
 		break;
 	}

 	ctx = bpf_ctx_init(kattr, sizeof(struct __sk_buff));
 	if (IS_ERR(ctx))
 		return PTR_ERR(ctx);

 	if (ctx) {
 		if (ctx->data_end > kattr->test.data_size_in || ctx->data || ctx->data_meta) {
 			ret = -EINVAL;
 			goto out;
 		}
 		if (ctx->data_end) {
 			/* Non-linear LWT test_run is unsupported for now. */
 			if (is_lwt) {
 				ret = -EINVAL;
 				goto out;
 			}
 			linear_sz = max(ETH_HLEN, ctx->data_end);
 		}
 	}

 	linear_sz = min_t(u32, linear_sz, PAGE_SIZE - headroom - tailroom);

 	data = bpf_test_init(kattr, linear_sz, linear_sz, headroom, tailroom);
 	if (IS_ERR(data)) {
 		ret = PTR_ERR(data);
 		data = NULL;
 		goto out;
 	}

 	sk = sk_alloc(net, AF_UNSPEC, GFP_USER, &bpf_dummy_proto, 1);
 	if (!sk) {
 		ret = -ENOMEM;
 		goto out;
 	}
 	sock_init_data(NULL, sk);

 	skb = slab_build_skb(data);
 	if (!skb) {
 		ret = -ENOMEM;
 		goto out;
 	}
 	skb->sk = sk;

 	data = NULL; /* data released via kfree_skb */

 	skb_reserve(skb, NET_SKB_PAD + NET_IP_ALIGN);
 	__skb_put(skb, linear_sz);

 	if (unlikely(kattr->test.data_size_in > linear_sz)) {
 		void __user *data_in = u64_to_user_ptr(kattr->test.data_in);
 		struct skb_shared_info *sinfo = skb_shinfo(skb);
 		u32 copied = linear_sz;

 		while (copied < kattr->test.data_size_in) {
 			struct page *page;
 			u32 data_len;

 			if (sinfo->nr_frags == MAX_SKB_FRAGS) {
 				ret = -ENOMEM;
 				goto out;
 			}

 			page = alloc_page(GFP_KERNEL);
 			if (!page) {
 				ret = -ENOMEM;
 				goto out;
 			}

 			data_len = min_t(u32, kattr->test.data_size_in - copied,
 					 PAGE_SIZE);
 			skb_fill_page_desc(skb, sinfo->nr_frags, page, 0, data_len);

 			if (copy_from_user(page_address(page), data_in + copied,
 					   data_len)) {
 				ret = -EFAULT;
 				goto out;
 			}
 			skb->data_len += data_len;
 			skb->truesize += PAGE_SIZE;
 			skb->len += data_len;
 			copied += data_len;
 		}
 	}

 	if (ctx && ctx->ifindex > 1) {
 		dev = dev_get_by_index(net, ctx->ifindex);
 		if (!dev) {
 			ret = -ENODEV;
 			goto out;
 		}
 	}
 	skb->protocol = eth_type_trans(skb, dev);
 	skb_reset_network_header(skb);

 	switch (skb->protocol) {
 	case htons(ETH_P_IP):
-		sk->sk_family = AF_INET;
-		if (sizeof(struct iphdr) <= skb_headlen(skb)) {
-			sk->sk_rcv_saddr = ip_hdr(skb)->saddr;
-			sk->sk_daddr = ip_hdr(skb)->daddr;
+		if (skb_headlen(skb) < sizeof(struct iphdr)) {
+			ret = -EINVAL;
+			goto out;
 		}
+		sk->sk_family = AF_INET;
+		sk->sk_rcv_saddr = ip_hdr(skb)->saddr;
+		sk->sk_daddr = ip_hdr(skb)->daddr;
 		break;
 #if IS_ENABLED(CONFIG_IPV6)
 	case htons(ETH_P_IPV6):
-		sk->sk_family = AF_INET6;
-		if (sizeof(struct ipv6hdr) <= skb_headlen(skb)) {
-			sk->sk_v6_rcv_saddr = ipv6_hdr(skb)->saddr;
-			sk->sk_v6_daddr = ipv6_hdr(skb)->daddr;
+		if (skb_headlen(skb) < sizeof(struct ipv6hdr)) {
+			ret = -EINVAL;
+			goto out;
 		}
+		sk->sk_family = AF_INET6;
+		sk->sk_v6_rcv_saddr = ipv6_hdr(skb)->saddr;
+		sk->sk_v6_daddr = ipv6_hdr(skb)->daddr;
 		break;
 #endif
 	default:
 		break;
 	}

 	if (is_l2)
 		__skb_push(skb, hh_len);
 	if (is_direct_pkt_access)
 		bpf_compute_data_pointers(skb);

 	ret = convert___skb_to_skb(skb, ctx);
 	if (ret)
 		goto out;

 	if (kattr->test.flags & BPF_F_TEST_SKB_CHECKSUM_COMPLETE) {
 		const int off = skb_network_offset(skb);
 		int len = skb->len - off;

 		skb->csum = skb_checksum(skb, off, len, 0);
 		skb->ip_summed = CHECKSUM_COMPLETE;
 	}

 	if (prog->type == BPF_PROG_TYPE_LWT_XMIT) {
 		if (!ipv6_mod_enabled()) {
 			pr_warn_once("Please test this program with IPv6 enabled kernel\n");
 			ret = -EOPNOTSUPP;
 			goto out;
 		}
 #if IS_ENABLED(CONFIG_IPV6)
 		dst_hold(&net->ipv6.ip6_null_entry->dst);
 		skb_dst_set(skb, &net->ipv6.ip6_null_entry->dst);
 #endif
 	}

 	ret = bpf_test_run(prog, skb, repeat, &retval, &duration, false);
 	if (ret)
 		goto out;
 	if (!is_l2) {
 		if (skb_headroom(skb) < hh_len) {
 			int nhead = HH_DATA_ALIGN(hh_len - skb_headroom(skb));

 			if (pskb_expand_head(skb, nhead, 0, GFP_USER)) {
 				ret = -ENOMEM;
 				goto out;
 			}
 		}
 		memset(__skb_push(skb, hh_len), 0, hh_len);
 	}

 	if (kattr->test.flags & BPF_F_TEST_SKB_CHECKSUM_COMPLETE) {
 		const int off = skb_network_offset(skb);
 		int len = skb->len - off;
 		__wsum csum;

 		csum = skb_checksum(skb, off, len, 0);

 		if (csum_fold(skb->csum) != csum_fold(csum)) {
 			ret = -EBADMSG;
 			goto out;
 		}
 	}

 	convert_skb_to___skb(skb, ctx);

 	if (skb_is_nonlinear(skb))
 		/* bpf program can never convert linear skb to non-linear */
 		WARN_ON_ONCE(linear_sz == kattr->test.data_size_in);
 	ret = bpf_test_finish(kattr, uattr, skb->data, skb_shinfo(skb), skb->len,
 			      skb->data_len, retval, duration);
 	if (!ret)
 		ret = bpf_ctx_finish(kattr, uattr, ctx,
 				     sizeof(struct __sk_buff));
 out:
 	if (dev && dev != net->loopback_dev)
 		dev_put(dev);
 	kfree_skb(skb);
 	kfree(data);
 	if (sk)
 		sk_free(sk);
 	kfree(ctx);
 	return ret;
 }



